# Sevlink LOCAL multiple-appointment update. STOP your local server first.
# Backs up the existing SQLite database and source; applies migrations through 0036.
# No live email, AWS deployment, account reset or uploaded-photo removal.
& {
  $ErrorActionPreference = 'Stop'
  $target = Join-Path $env:USERPROFILE 'OneDrive\Desktop\SEVLINK\Sevlink test 4\sevlink-platform-development-phase-1-foundations\portal\production'
  $python = Join-Path $target '.venv\Scripts\python.exe'
  $database = Join-Path $target 'development.sqlite3'
  foreach ($required in @($python, $database, (Join-Path $target 'manage.py'))) {
    if (!(Test-Path -LiteralPath $required -PathType Leaf)) { throw 'Existing local installation missing. Nothing changed; send this error to Codex.' }
  }
  $running = Get-CimInstance Win32_Process | Where-Object { $_.ExecutablePath -ieq $python -and $_.CommandLine -match 'manage.py.*runserver' }
  if ($running) { throw 'Stop the black website server with Ctrl+C, then run this update again. Nothing changed.' }
  $files = @(
    @{ Name = 'portal/migrations/0035_optional_assignment_city.py'; Hash = '5b018e6bc4275dd24967e19c4f301805884253bac7bffebbde95491971aeff8f'; Data = '' },
    @{ Name = 'portal/suppliers.py'; Hash = 'ae28308713a7621a893fd98d24748a674df8fe4a5ab313a444f64e5479d55702'; Data = '' },
    @{ Name = 'portal/scheduling.py'; Hash = '2e2fbb7e6b71c8221d8253fb53ae03efb31e1d455d65cc3f800cc9db7c377e29'; Data = '' },
    @{ Name = 'portal/regions.py'; Hash = 'd17307e108275d91852a9a43913d685e7d55271a8784042e05f461364e6c9134'; Data = '' },
    @{ Name = 'templates/portal/dashboard.html'; Hash = '2a949e17241b8503967ee80001ef173b3f0f31695ac785378cba1edab075c547'; Data = '' },
    @{ Name = 'config/settings.py'; Hash = '6d53bbfded904100356834b570adae0aecc62c61ca21af23066be700f053977e'; Data = '' },
    @{ Name = 'portal/migrations/0034_removal_receipt.py'; Hash = '732a03755de31d684839d4604ef2535c1654bf3c04fc134a04725bf5664f54e1'; Data = '' },
    @{ Name = 'portal/admin_controls.py'; Hash = '4c8889c9cece244f25cd949341d149675a368a0c3f328d54afc3f293b695ce64'; Data = '' },
    @{ Name = 'portal/quotations.py'; Hash = '6c4b11b71aa2dc31a09eaffcf7aabff1bf4f6d56f3433d999e9b94e5043e6470'; Data = '' },
    @{ Name = '../dist/features.css'; Hash = '27eb5c5d4014e835b3c793ac86ab42e2c8e2e4fc3da4137b74e210f6db55fbea'; Data = '' },
    @{ Name = 'portal/events.py'; Hash = 'f1da6e746115956b07737d828aa3be7e728ead78bc13e5db9d38d9e505f83735'; Data = '' },
    @{ Name = 'portal/operations.py'; Hash = '7835552de7937350636a306bcf93b3b3eefc8d069fbb807f02b5ada5eb95799d'; Data = '' },
    @{ Name = 'config/urls.py'; Hash = '04e86bd2483005e68ae21d4914d209df586c244945bfda59df6d7a7d1e1b61c7'; Data = '' },
    @{ Name = 'portal/models.py'; Hash = '6d9466820811aef10b65062b85216056950281df43c3f38a7fd0cfb6f0046246'; Data = '' },
    @{ Name = 'portal/attachments.py'; Hash = '355d5e270fd57284c3c79af1b15deffef5a798dde89e2dc019a139b48bc615a6'; Data = '' },
    @{ Name = 'portal/account_mail.py'; Hash = '6144e856e996bb65e6051f8166e4d21180466f7b72404a66dfd21ddf3392823e'; Data = '' },
    @{ Name = 'portal/completion_delivery.py'; Hash = 'de6c0fc8dbaa7876905a24f3bd03d62c3a381435420b811ce27c89f8de91e7c4'; Data = '' },
    @{ Name = 'portal/invoices.py'; Hash = '8390abf5186f12b508e03adf84187bacf01f097cae8960d488ff50fab5f7e0a9'; Data = '' },
    @{ Name = 'portal/maintenance.py'; Hash = '00a3db56b70b9e7e3369b246febbab825d41f5998411d24347701ab6730850b1'; Data = '' },
    @{ Name = 'portal/workflow.py'; Hash = 'ef8cf21bd0516ba0661187707b7ad2534808854825ce779694bd061626f72a5b'; Data = '' },
    @{ Name = 'portal/customer_portal.py'; Hash = '0fa0f132b9a2f312f552550148c6eb26ff88e1b6bddf55d6f32a4abf02dd4fd7'; Data = '' },
    @{ Name = 'portal/migrations/0033_completionpackage.py'; Hash = '458ea2a5b06b42db356341c0b34e1d4085500fa97dc43237ffdaa304c5306c29'; Data = '' },
    @{ Name = 'static/maintenance.js'; Hash = '58a7977176992a964d65d47d956f3f23701fb9b396fa48dd5070cdbf80e2cf19'; Data = '' },
    @{ Name = 'static/workflow-ui.js'; Hash = 'dc5077a58ce33ff0cbba819708cbe2d25d77edf821f4aa1e05a221f8b3d05476'; Data = '' },
    @{ Name = 'static/workflow.css'; Hash = '75d76119d5ed12c952470ea4bd65688179522f6e8a8a67797fa86fa6e10ac02c'; Data = '' },
    @{ Name = 'static/calendar.css'; Hash = '80fd9d6a0549d5c44b6a1fed918ee598327712bf92ec939da22775fb2c1ebc57'; Data = '' },
    @{ Name = 'portal/migrations/0036_appointment_progress.py'; Hash = '202b5d61a51ebc97fb0586327f561782221a6168412d30b6641cd296da13a1fb'; Data = '' }
  )
  $decoded = @{}
  foreach ($file in $files) {
    $file.Existed = Test-Path -LiteralPath (Join-Path $target $file.Name) -PathType Leaf
    $compressed = [Convert]::FromBase64String($file.Data)
    $inputStream = [IO.MemoryStream]::new($compressed)
    $gzipStream = [IO.Compression.GZipStream]::new($inputStream, [IO.Compression.CompressionMode]::Decompress)
    $outputStream = [IO.MemoryStream]::new()
    try { $gzipStream.CopyTo($outputStream); $bytes = $outputStream.ToArray() }
    finally { $gzipStream.Dispose(); $inputStream.Dispose(); $outputStream.Dispose() }
    $sha = [Security.Cryptography.SHA256]::Create()
    try { $hash = [BitConverter]::ToString($sha.ComputeHash($bytes)).Replace('-', '').ToLowerInvariant() }
    finally { $sha.Dispose() }
    if ($hash -ne $file.Hash) { throw 'Payload integrity check failed. Nothing changed.' }
    $decoded[$file.Name] = $bytes
  }
  $backup = Join-Path $env:LOCALAPPDATA ('Sevlink\Backups\multiple-appointments-' + [Guid]::NewGuid().ToString('N'))
  New-Item -ItemType Directory -Path $backup | Out-Null
  $databaseBackup = Join-Path $backup 'development.sqlite3'
  $backupCode = @'
import sqlite3,sys
from pathlib import Path
with sqlite3.connect(Path(sys.argv[1]).resolve().as_uri()+'?mode=ro',uri=True) as source:
    if not source.execute("SELECT 1 FROM django_migrations WHERE app='portal' AND name='0032_workflow_database_guards'").fetchone():
        raise SystemExit('Expected existing 0032 database not found. Stop and ask Codex; nothing changed.')
    names=[row[0] for row in source.execute("SELECT name FROM django_migrations WHERE app='portal'")]
    if any(int(name.split('_',1)[0])>36 for name in names if name.split('_',1)[0].isdigit()):
        raise SystemExit('This database is newer than this updater. Nothing changed.')
    with sqlite3.connect(sys.argv[2]) as backup:
        source.backup(backup)
        if backup.execute('PRAGMA integrity_check').fetchone()[0]!='ok':raise SystemExit('Backup integrity check failed.')
print('Existing database backup verified.')
'@
  $backupCode | & $python - $database $databaseBackup
  if ($LASTEXITCODE -ne 0) { throw 'Database backup failed; no source changed.' }
  foreach ($file in $files) {
    if ($file.Existed) { Copy-Item -LiteralPath (Join-Path $target $file.Name) -Destination (Join-Path $backup ($file.Name.Replace('/', '__'))) }
  }
  $names = @('DEBUG','DB_HOST','DJANGO_SECRET_KEY','SMTP_DELIVERY_ENABLED','OPERATIONS_LIVE_DELIVERY_ENABLED')
  $previous = @{}
  foreach ($name in $names) { $previous[$name] = [Environment]::GetEnvironmentVariable($name,'Process') }
  $migrationStarted = $false
  try {
    foreach ($file in $files) { [IO.File]::WriteAllBytes((Join-Path $target $file.Name),$decoded[$file.Name]) }
    foreach ($file in $files) {
      if ((Get-FileHash -LiteralPath (Join-Path $target $file.Name) -Algorithm SHA256).Hash.ToLowerInvariant() -ne $file.Hash) { throw ('Saved file check failed: '+$file.Name) }
    }
    $env:DEBUG='1';$env:DB_HOST='';$env:SMTP_DELIVERY_ENABLED='0';$env:OPERATIONS_LIVE_DELIVERY_ENABLED='0'
    if (!$env:DJANGO_SECRET_KEY) { $env:DJANGO_SECRET_KEY = & $python -c 'import secrets; print(secrets.token_urlsafe(64))' }
    $migrationStarted = $true
    & $python -X utf8 (Join-Path $target 'manage.py') migrate portal '0036' --noinput
    if ($LASTEXITCODE -ne 0) { throw 'Migration failed; restoring the previous local version.' }
    & $python -X utf8 (Join-Path $target 'manage.py') check
    if ($LASTEXITCODE -ne 0) { throw 'Application check failed; restoring the previous local version.' }
  } catch {
    $failure = $_
    foreach ($file in $files) {
      if ($file.Existed) { Copy-Item -LiteralPath (Join-Path $backup ($file.Name.Replace('/', '__'))) -Destination (Join-Path $target $file.Name) -Force }
      elseif (Test-Path -LiteralPath (Join-Path $target $file.Name)) { Remove-Item -LiteralPath (Join-Path $target $file.Name) }
    }
    if ($migrationStarted) {
      $restoreCode = 'import sqlite3,sys; source=sqlite3.connect(sys.argv[1]); target=sqlite3.connect(sys.argv[2]); source.backup(target); target.close(); source.close()'
      $restoreCode | & $python - $databaseBackup $database
      if ($LASTEXITCODE -ne 0) { Write-Host ('RESTORE NEEDS REVIEW. Preserve backup: '+$backup) -ForegroundColor Red }
    }
    throw $failure
  } finally {
    foreach ($name in $names) { [Environment]::SetEnvironmentVariable($name,$previous[$name],'Process') }
  }
  Write-Host ''
  Write-Host 'SUCCESS: Multiple appointments, individual statuses and manual rescheduling are ready.' -ForegroundColor Green
  Write-Host ('Database and source backup: '+$backup)
  Write-Host 'Existing accounts, payments and uploaded files are preserved.'
  Write-Host 'Real email sending has NOT been enabled.'
  Write-Host 'Restart your original local server and press Ctrl+F5 in the browser.'
}
